concatenated_list = urls +  flattened_profs

final_list = [url for url in concatenated_list if url not in exclusions]

import os
import time
import requests
import csv
from PIL import Image
from io import BytesIO

output_folder = './../images/outfits'

csv_file = './../data/outfits.csv'

if not os.path.exists(output_folder):
    os.makedirs(output_folder)

with open(csv_file, mode='w', newline='', encoding='utf-8') as file:
    writer = csv.writer(file)

    writer.writerow(['id', 'url', 'type', 'filename'])

    for idx, url in enumerate(final_list, start=1):
        try:
            print(f"Przetwarzanie elementu {idx} z {len(final_list)}: {url}")

            response = requests.get(url)
            response.raise_for_status()

            url_type = url.split('/')[-2]

            last_part = url.split('/')[-1].split('.')[0]

            filename = f"{idx:06d}_{last_part}.png"
            file_path = os.path.join(output_folder, filename)

            if url.lower().endswith('.gif'):
                with Image.open(BytesIO(response.content)) as img:
                    img.seek(0)
                    img.save(file_path, 'PNG')
            else:
                with Image.open(BytesIO(response.content)) as img:
                    img.save(file_path, 'PNG')

            writer.writerow([idx, url, url_type, filename])

            print(f"Zapisano plik: {file_path}")

        except Exception as e:
            print(f"Błąd podczas przetwarzania {url}: {e}")

        time.sleep(0.7)

print("Przetwarzanie zakończone.")